const nombre = prompt("Tu nombre");
const meta = prompt("Tu meta");
const textoMinutos = prompt("Minutos diarios");
const minutos = Number(textoMinutos);
const dias = 5;
const referencia = 20;
const total = minutos * dias;
const minutosAmpliados = minutos + 5;
const totalAmpliado = minutosAmpliados * dias;
console.log("Hola TeslaCode");
console.log("Mi plan de práctica");
console.log("Estado: listo");
console.log("Sesión: JavaScript");
console.log("Minutos diarios:", minutos);
console.log("Días:", dias);
console.log("Meta:", meta);
console.log("Recordatorio:", meta);
console.log("Referencia diaria:", referencia);
console.log("Total:", total);
console.log("Nombre:", nombre);
console.log("Plan con 5 más:", totalAmpliado);
console.log("Tipo de minutos:", typeof minutos);

